#include <iostream>
#include <set>
using namespace std;

int main() {
    set<int> s;
    s.insert(3); s.insert(1); s.insert(4); s.insert(1);
    for (int x : s) cout << x << " ";
    cout << endl;
    cout << s.count(3) << endl;
    auto it = s.lower_bound(2);
    cout << *it << endl;
    return 0;
}

#include <iostream>
#include <map>
using namespace std;

int main() {
    map<string, int> mp;
    mp["apple"] = 3;
    mp["banana"] = 5;
    mp["apple"]++;
    for (auto& [k, v] : mp)
        cout << k << ": " << v << endl;
    return 0;
}

#include <iostream>
#include <unordered_map>
using namespace std;

int main() {
    unordered_map<string, int> cnt;
    int n;
    cin >> n;
    for (int i = 0; i < n; i++) {
        string s;
        cin >> s;
        cnt[s]++;
    }
    for (auto& [k, v] : cnt)
        cout << k << " " << v << endl;
    return 0;
}

#include <iostream>
#include <set>
using namespace std;

int main() {
    multiset<int> ms;
    ms.insert(3);
    ms.insert(1);
    ms.insert(3);
    ms.insert(2);
    for (int x : ms) cout << x << " ";
    cout << endl;
    cout << "count(3): " << ms.count(3) << endl;
    auto it = ms.find(3);
    if (it != ms.end()) ms.erase(it);
    for (int x : ms) cout << x << " ";
    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    pair<int, int> p = {3, 5};
    cout << p.first << " " << p.second << endl;
    vector<pair<int, int>> v = {{3, 1}, {1, 2}, {2, 3}};
    sort(v.begin(), v.end());
    for (auto& x : v) cout << x.first << "," << x.second << " ";
    return 0;
}

#include <iostream>
#include <tuple>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    auto t = make_tuple(3, 2, 1);
    cout << get<0>(t) << " " << get<1>(t) << " " << get<2>(t) << endl;
    int a, b, c;
    tie(a, b, c) = t;
    cout << a << " " << b << " " << c << endl;
    vector<tuple<int,int,int>> v;
    v.push_back({3, 2, 1});
    v.push_back({1, 5, 3});
    v.push_back({1, 2, 4});
    sort(v.begin(), v.end());
    for (auto& x : v) cout << get<0>(x) << "," << get<1>(x) << "," << get<2>(x) << " ";
    return 0;
}
